-- 225: transport runtime, source inbox and independently reviewed external punches.
-- Private staging until dual-driver validation. Existing001–224 bytes stay immutable.
CREATE TABLE ty_ix_profile(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 version integer NOT NULL CHECK(version>0),application_type text NOT NULL CHECK(application_type IN('internal','third_party','delegated','gateway')),
 enabled_capabilities text[] NOT NULL,settings jsonb NOT NULL DEFAULT '{}',scope_evidence_ref text NOT NULL CHECK(length(btrim(scope_evidence_ref))>=4),
 expected_connection_revision integer NOT NULL,expected_secret_revision integer NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,
 UNIQUE(connection_id,version),UNIQUE(id,group_id),CHECK(cardinality(enabled_capabilities)>0)
);
CREATE TABLE ty_ix_identity(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 external_kind text NOT NULL CHECK(external_kind IN('person','department','company')),external_id text NOT NULL CHECK(length(external_id)BETWEEN 1 AND 200),
 person_id bigint REFERENCES ty_person(id),employment_id bigint REFERENCES ty_employment(id),department_id bigint REFERENCES ty_department(id),local_company_id bigint REFERENCES ty_company(id),
 valid_from date NOT NULL,valid_to date,evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 status text NOT NULL DEFAULT'proposed'CHECK(status IN('proposed','approved','rejected','disabled')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK((external_kind='person'AND person_id IS NOT NULL AND department_id IS NULL AND local_company_id IS NULL)OR(external_kind='department'AND person_id IS NULL AND employment_id IS NULL AND department_id IS NOT NULL AND local_company_id IS NULL)OR(external_kind='company'AND person_id IS NULL AND employment_id IS NULL AND department_id IS NULL AND local_company_id IS NOT NULL)),
 EXCLUDE USING gist(connection_id WITH=,external_kind WITH=,external_id WITH=,daterange(valid_from,valid_to,'[)')WITH&&)WHERE(status='approved')
);
CREATE TABLE ty_ix_cursor(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 kind text NOT NULL,partition_key text NOT NULL,position jsonb NOT NULL DEFAULT '{}',covered_from timestamptz,covered_to timestamptz,revision integer NOT NULL DEFAULT 1,
 updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,kind,partition_key),CHECK(covered_to IS NULL OR covered_from IS NOT NULL AND covered_to>=covered_from)
);
CREATE TABLE ty_ix_job(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),profile_id bigint NOT NULL REFERENCES ty_ix_profile(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 kind text NOT NULL CHECK(kind IN('directory.read','directory.write','punch.read','punch.write','message.send','task.send','approval.receive')),
 source_key text NOT NULL,request jsonb NOT NULL,input_hash text NOT NULL,cursor_id bigint REFERENCES ty_ix_cursor(id),expected_cursor_revision integer,
 state text NOT NULL DEFAULT'queued'CHECK(state IN('queued','leased','retry_wait','completed','blocked','failed','remote_unknown','cancelled')),
 lease_token text,lease_until timestamptz,lease_owner text,attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),available_at timestamptz NOT NULL DEFAULT now(),
 remote_id text,result jsonb NOT NULL DEFAULT '{}',error_code text,revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,
 UNIQUE(connection_id,kind,source_key),CHECK((state='leased'AND lease_token IS NOT NULL AND lease_owner IS NOT NULL AND lease_until IS NOT NULL)OR(state<>'leased'AND lease_token IS NULL AND lease_owner IS NULL AND lease_until IS NULL)),
 CHECK((cursor_id IS NULL)=(expected_cursor_revision IS NULL))
);
CREATE UNIQUE INDEX ty_ix_cursor_inflight ON ty_ix_job(cursor_id)WHERE cursor_id IS NOT NULL AND state IN('queued','leased','retry_wait');
CREATE INDEX ty_ix_job_due ON ty_ix_job(state,available_at,lease_until,id);
CREATE TABLE ty_ix_event_root(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 event_kind text NOT NULL CHECK(event_kind IN('attendance_raw','door_event','directory_person','directory_department','approval_result','delivery_receipt','unknown')),
 external_id text NOT NULL,latest_inbox_id bigint,approved_punch_id bigint,head_revision integer NOT NULL DEFAULT 0,
 latest_source_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,event_kind,external_id),UNIQUE(id,group_id)
);
CREATE TABLE ty_ix_callback_envelope(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),profile_id bigint NOT NULL REFERENCES ty_ix_profile(id),
 nonce_hash text NOT NULL,signature_hash text NOT NULL,body_sha256 text NOT NULL,headers jsonb NOT NULL,payload_cipher text NOT NULL,payload_iv text NOT NULL,payload_tag text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(connection_id,nonce_hash),UNIQUE(id,connection_id,group_id)
);
CREATE TABLE ty_ix_inbox(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,root_id bigint NOT NULL REFERENCES ty_ix_event_root(id),connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 callback_envelope_id bigint,job_id bigint REFERENCES ty_ix_job(id),source_version text NOT NULL,source_at timestamptz,occurred_at timestamptz,received_at timestamptz NOT NULL DEFAULT now(),
 payload_hash text NOT NULL,payload_cipher text NOT NULL,payload_iv text NOT NULL,payload_tag text NOT NULL,normalized jsonb NOT NULL DEFAULT '{}',
 verification text NOT NULL CHECK(verification IN('provider_response','verified_callback','signed_gateway','reviewed_file')),
 state text NOT NULL DEFAULT'pending'CHECK(state IN('pending','reviewed','quarantined','rejected','stale')),reviewed_by bigint REFERENCES sys_account(id),review_reason text,revision integer NOT NULL DEFAULT 1,
 UNIQUE(root_id,source_version),FOREIGN KEY(callback_envelope_id,connection_id,group_id)REFERENCES ty_ix_callback_envelope(id,connection_id,group_id)
);
ALTER TABLE ty_ix_event_root ADD CONSTRAINT ty_ix_root_inbox FOREIGN KEY(latest_inbox_id)REFERENCES ty_ix_inbox(id);
CREATE TABLE ty_ix_punch(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,root_id bigint NOT NULL REFERENCES ty_ix_event_root(id),inbox_id bigint NOT NULL REFERENCES ty_ix_inbox(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),identity_id bigint NOT NULL REFERENCES ty_ix_identity(id),
 work_company_id bigint NOT NULL REFERENCES ty_company(id),department_id bigint NOT NULL REFERENCES ty_department(id),segment_ref text NOT NULL,direction text NOT NULL CHECK(direction IN('in','out')),punched_at timestamptz NOT NULL,
 source_hash text NOT NULL,expected_root_head integer NOT NULL,source_timezone text NOT NULL,clock_state text NOT NULL CHECK(clock_state IN('trusted','late_upload','drift_reviewed')),
 evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),reason text NOT NULL CHECK(length(btrim(reason))>=4),
 status text NOT NULL DEFAULT'proposed'CHECK(status IN('proposed','approved','rejected')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz
);
ALTER TABLE ty_ix_event_root ADD CONSTRAINT ty_ix_root_approved_punch FOREIGN KEY(approved_punch_id)REFERENCES ty_ix_punch(id);
CREATE TABLE ty_ix_delivery_receipt(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,job_id bigint NOT NULL REFERENCES ty_ix_job(id),connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 attempt integer NOT NULL,request_hash text NOT NULL,response_hash text,http_status integer,provider_code text,remote_id text,
 outcome text NOT NULL CHECK(outcome IN('confirmed','rejected','unknown','rate_limited','read_failed','stale_lease')),
 network_mode text NOT NULL CHECK(network_mode IN('provider','gateway','fixture')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,attempt)
);
CREATE TABLE ty_ix_callback_nonce(
 connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),nonce_hash text NOT NULL,signature_hash text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,
 PRIMARY KEY(connection_id,nonce_hash),CHECK(expires_at>received_at)
);
CREATE TABLE ty_ix_reconciliation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,job_id bigint NOT NULL REFERENCES ty_ix_job(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 outcome text NOT NULL CHECK(outcome IN('confirmed_sent','confirmed_not_sent','still_unknown')),remote_id text,evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),reason text NOT NULL CHECK(length(btrim(reason))>=4),
 actor_id bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION fn_ty_ix_company_contains(parent_key bigint,child_key bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$WITH RECURSIVE c AS(SELECT id FROM public.ty_company WHERE id=parent_key UNION ALL SELECT x.id FROM public.ty_company x JOIN c ON x.parent_company_id=c.id)SELECT parent_key IS NULL OR EXISTS(SELECT 1 FROM c WHERE id=child_key)$$;
CREATE FUNCTION fn_ty_ix_scope_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE j jsonb=to_jsonb(NEW);c public.ty_integration_connection%ROWTYPE;e public.ty_employment%ROWTYPE;g bigint=(j->>'group_id')::bigint;co bigint=(j->>'company_id')::bigint;BEGIN
 SELECT*INTO c FROM public.ty_integration_connection WHERE id=(j->>'connection_id')::bigint;
 IF c.id IS NOT NULL AND(c.group_id IS DISTINCT FROM g OR co IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company x WHERE x.id=co AND x.group_id=g)OR c.company_id IS NOT NULL AND co IS NOT NULL AND NOT public.fn_ty_ix_company_contains(c.company_id,co))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 集成对象与连接集团公司范围不符';END IF;
 IF(j->>'person_id')IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_person WHERE id=(j->>'person_id')::bigint AND group_id=g)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 外部映射必须既有同集团永久人';END IF;
 IF(j->>'employment_id')IS NOT NULL THEN SELECT*INTO e FROM public.ty_employment WHERE id=(j->>'employment_id')::bigint;IF e.id IS NULL OR e.group_id IS DISTINCT FROM g OR e.person_id IS DISTINCT FROM(j->>'person_id')::bigint OR co IS NOT NULL AND e.company_id<>co THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 外部来源不得换人或造另一实际关系';END IF;END IF;
 IF TG_TABLE_NAME='ty_ix_identity'THEN IF NEW.department_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_department d JOIN public.ty_company company ON company.id=d.company_id WHERE d.id=NEW.department_id AND company.group_id=g AND(co IS NULL OR d.company_id=co))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 映射部门不属于本集团公司';END IF;END IF;
 RETURN NEW;END;$$;
CREATE FUNCTION fn_ty_ix_frozen_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE o jsonb=to_jsonb(OLD);n jsonb=to_jsonb(NEW);mutable text[];BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 集成来源历史不得删除';END IF;
 IF TG_TABLE_NAME='ty_ix_profile'THEN mutable=ARRAY['status','revision','approved_by','approved_at'];
 ELSIF TG_TABLE_NAME IN('ty_ix_identity','ty_ix_directory_proposal')THEN mutable=ARRAY['status','revision','approved_by'];
 ELSIF TG_TABLE_NAME='ty_ix_job'THEN mutable=ARRAY['runtime_profile_id','state','lease_token','lease_until','lease_owner','attempts','available_at','remote_id','result','error_code','revision','completed_at'];
 ELSIF TG_TABLE_NAME='ty_ix_event_root'THEN mutable=ARRAY['latest_inbox_id','approved_punch_id','head_revision','latest_source_at'];
 ELSIF TG_TABLE_NAME='ty_ix_inbox'THEN mutable=ARRAY['state','reviewed_by','review_reason','revision'];
 ELSIF TG_TABLE_NAME='ty_ix_punch'THEN mutable=ARRAY['status','revision','approved_by','approved_at'];
 ELSIF TG_TABLE_NAME='ty_ix_cursor'THEN mutable=ARRAY['position','covered_from','covered_to','revision','updated_at'];ELSE mutable=ARRAY[]::text[];END IF;
 IF(n-mutable)IS DISTINCT FROM(o-mutable)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已落集成身份来源及载荷不可覆盖，须新版本';END IF;RETURN NEW;END;$$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['profile','identity','cursor','job','event_root','inbox','punch','delivery_receipt','callback_envelope']LOOP EXECUTE format('CREATE TRIGGER ty_ix_%s_scope BEFORE INSERT OR UPDATE ON ty_ix_%s FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_scope_guard()',n,n);EXECUTE format('CREATE TRIGGER ty_ix_%s_frozen BEFORE UPDATE OR DELETE ON ty_ix_%s FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_frozen_guard()',n,n);END LOOP;END$$;
CREATE FUNCTION fn_ty_ix_approval_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE author bigint;reviewer bigint;person bigint;BEGIN
 author=NEW.created_by;reviewer=NEW.approved_by;
 IF TG_TABLE_NAME='ty_ix_profile'AND NEW.status='approved'THEN IF NOT EXISTS(SELECT 1 FROM public.ty_integration_connection WHERE id=NEW.connection_id AND status='active'AND secret_cipher IS NOT NULL AND revision=NEW.expected_connection_revision AND secret_revision=NEW.expected_secret_revision)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 核准运行规则须对应当前已配置连接及凭据版本';END IF;END IF;
 IF NEW.status='approved'THEN IF reviewer IS NULL OR public.fn_ty_pr_same_actor(author,reviewer)OR TG_TABLE_NAME IN('ty_ix_identity','ty_ix_punch','ty_ix_directory_proposal')AND(to_jsonb(NEW)->>'person_id')IS NOT NULL AND public.fn_ty_pr_actor_is_person(reviewer,NEW.group_id,(to_jsonb(NEW)->>'person_id')::bigint)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 集成配置映射及原卡须真实独立核准';END IF;END IF;
 IF TG_OP='UPDATE'AND OLD.status IN('rejected','disabled')AND NEW.status<>OLD.status OR TG_OP='UPDATE'AND OLD.status='approved'AND NEW.status NOT IN('approved','disabled')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已核来源不得回退冒充未审核';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_profile_approval BEFORE INSERT OR UPDATE ON ty_ix_profile FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_approval_guard();
CREATE TRIGGER ty_ix_identity_approval BEFORE INSERT OR UPDATE ON ty_ix_identity FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_approval_guard();
CREATE TRIGGER ty_ix_punch_approval BEFORE INSERT OR UPDATE ON ty_ix_punch FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_approval_guard();
CREATE FUNCTION fn_ty_ix_segment_context(segment_ref text)RETURNS TABLE(group_id bigint,person_id bigint,employment_id bigint,home_company_id bigint,work_company_id bigint,department_id bigint,work_date date,start_at timestamptz,end_at timestamptz,source_status text)LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT p.group_id,d.person_id,d.employment_id,d.home_company_id,s.work_company_id,s.department_id,d.work_date,s.start_at AT TIME ZONE'Asia/Shanghai',s.end_at AT TIME ZONE'Asia/Shanghai',p.status FROM public.ty_roster_segment s JOIN public.ty_roster_day d ON d.id=s.day_id JOIN public.ty_roster_period p ON p.id=d.period_id WHERE segment_ref~'^base:[1-9][0-9]*$'AND s.id=CASE WHEN segment_ref~'^base:[1-9][0-9]*$'THEN substring(segment_ref FROM 6)::bigint END
 UNION ALL SELECT p.group_id,s.person_id,s.employment_id,s.home_company_id,s.work_company_id,s.department_id,s.work_date,s.start_at,s.end_at,p.status FROM public.ty_time_plan_segment s JOIN public.ty_time_plan_version p ON p.id=s.plan_id WHERE segment_ref~'^plan:[1-9][0-9]*$'AND s.id=CASE WHEN segment_ref~'^plan:[1-9][0-9]*$'THEN substring(segment_ref FROM 6)::bigint END AND s.state='active'
 $$;
CREATE FUNCTION fn_ty_ix_punch_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE root public.ty_ix_event_root%ROWTYPE;inbox public.ty_ix_inbox%ROWTYPE;identity public.ty_ix_identity%ROWTYPE;e public.ty_employment%ROWTYPE;d date;seg record;BEGIN
 SELECT*INTO seg FROM public.fn_ty_ix_segment_context(NEW.segment_ref);SELECT*INTO root FROM public.ty_ix_event_root WHERE id=NEW.root_id FOR UPDATE;SELECT*INTO inbox FROM public.ty_ix_inbox WHERE id=NEW.inbox_id;SELECT*INTO identity FROM public.ty_ix_identity WHERE id=NEW.identity_id;SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;d=(NEW.punched_at AT TIME ZONE'Asia/Shanghai')::date;
 IF root.event_kind<>'attendance_raw'OR inbox.root_id<>root.id OR root.group_id<>NEW.group_id OR identity.connection_id<>root.connection_id OR identity.person_id<>NEW.person_id OR identity.external_id IS DISTINCT FROM inbox.normalized->>'external_user_id'OR identity.status<>'approved'OR d<identity.valid_from OR(identity.valid_to IS NOT NULL AND d>=identity.valid_to)OR(identity.employment_id IS NOT NULL AND identity.employment_id<>NEW.employment_id)OR e.id IS NULL OR e.group_id<>NEW.group_id OR e.person_id<>NEW.person_id OR e.company_id<>NEW.company_id OR e.status='cancelled'OR seg.work_date<e.hire_date OR(e.leave_date IS NOT NULL AND seg.work_date>e.leave_date)OR seg.group_id IS DISTINCT FROM NEW.group_id OR seg.person_id IS DISTINCT FROM NEW.person_id OR seg.employment_id IS DISTINCT FROM NEW.employment_id OR seg.home_company_id IS DISTINCT FROM NEW.company_id OR seg.work_company_id IS DISTINCT FROM NEW.work_company_id OR seg.department_id IS DISTINCT FROM NEW.department_id OR seg.source_status NOT IN('published','closed')OR NEW.punched_at>clock_timestamp()+interval'2 minutes'OR NEW.punched_at<seg.start_at-interval'4 hours'OR NEW.punched_at>seg.end_at+interval'6 hours'OR(inbox.normalized->>'direction'IS NOT NULL AND inbox.normalized->>'direction'IS DISTINCT FROM NEW.direction)OR NEW.punched_at IS DISTINCT FROM inbox.occurred_at OR NEW.source_hash<>inbox.payload_hash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 原卡必须沿确切来源、有效映射及实际关系，不以姓名或部门猜人';END IF;
 IF NEW.status='approved'AND(TG_OP='INSERT'OR OLD.status<>'approved')THEN IF root.latest_inbox_id IS DISTINCT FROM NEW.inbox_id OR root.head_revision<>NEW.expected_root_head THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='E_TY_CONFLICT: 外部事件已有新版本，请重新核查';END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_punch_source BEFORE INSERT OR UPDATE ON ty_ix_punch FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_punch_guard();
CREATE VIEW ty_ix_effective_punch AS SELECT p.id,p.group_id,p.company_id,p.person_id,p.employment_id,p.work_company_id,p.department_id,p.segment_ref,p.direction,p.punched_at,p.source_hash,p.inbox_id,p.root_id FROM ty_ix_punch p JOIN ty_ix_event_root r ON r.id=p.root_id WHERE p.status='approved'AND r.approved_punch_id=p.id AND r.latest_inbox_id=p.inbox_id;
-- Frozen source evidence belongs to a newly calculated draft, never to an old
-- confirmed report. A changed inbox head blocks new confirmation, not history.
CREATE TABLE ty_ix_report_evidence(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 report_id bigint NOT NULL REFERENCES ty_time_report_version(id),line_id bigint NOT NULL REFERENCES ty_time_report_line(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 punch_id bigint NOT NULL REFERENCES ty_ix_punch(id),root_id bigint NOT NULL REFERENCES ty_ix_event_root(id),inbox_id bigint NOT NULL REFERENCES ty_ix_inbox(id),
 expected_root_head integer NOT NULL,source_hash text NOT NULL,report_segment_ref text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(line_id,punch_id)
);
CREATE FUNCTION fn_ty_ix_source_in_lineage(target_ref text,source_ref text)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 WITH RECURSIVE chain AS(
 SELECT s.*,v.source_plan_id parent_plan FROM public.ty_time_plan_segment s JOIN public.ty_time_plan_version v ON v.id=s.plan_id WHERE target_ref~'^plan:[1-9][0-9]*$'AND s.id=CASE WHEN target_ref~'^plan:[1-9][0-9]*$'THEN substring(target_ref FROM 6)::bigint END
 UNION ALL SELECT p.*,v.source_plan_id FROM chain c JOIN public.ty_time_plan_segment p ON p.id=c.source_segment_id JOIN public.ty_time_plan_version v ON v.id=p.plan_id WHERE c.person_id=p.person_id AND c.employment_id=p.employment_id AND c.work_date=p.work_date AND(c.replaces_segment_id=p.id OR c.parent_plan=p.plan_id)
 )SELECT target_ref=source_ref OR EXISTS(SELECT 1 FROM chain WHERE 'plan:'||id=source_ref OR source_segment_id IS NULL AND chain.source_ref=fn_ty_ix_source_in_lineage.source_ref)
 $$;
CREATE FUNCTION fn_ty_ix_report_evidence_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE v public.ty_time_report_version%ROWTYPE;l public.ty_time_report_line%ROWTYPE;p public.ty_ix_punch%ROWTYPE;r public.ty_ix_event_root%ROWTYPE;BEGIN
 SELECT*INTO v FROM public.ty_time_report_version WHERE id=NEW.report_id;SELECT*INTO l FROM public.ty_time_report_line WHERE id=NEW.line_id;SELECT x.*INTO p FROM public.ty_ix_punch x JOIN public.ty_ix_effective_punch current ON current.id=x.id WHERE x.id=NEW.punch_id;SELECT*INTO r FROM public.ty_ix_event_root WHERE id=NEW.root_id FOR SHARE;
 IF v.status<>'draft'OR v.group_id IS DISTINCT FROM NEW.group_id OR l.report_id IS DISTINCT FROM v.id OR l.person_id IS DISTINCT FROM p.person_id OR l.employment_id IS DISTINCT FROM p.employment_id OR p.root_id IS DISTINCT FROM r.id OR p.inbox_id IS DISTINCT FROM NEW.inbox_id OR p.source_hash IS DISTINCT FROM NEW.source_hash OR r.head_revision IS DISTINCT FROM NEW.expected_root_head OR NOT(l.source_segment_ids? NEW.report_segment_ref)OR NOT public.fn_ty_ix_source_in_lineage(NEW.report_segment_ref,p.segment_ref)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 核勤须引用该报告行的已核原卡和确切来源头';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_report_evidence_scope BEFORE INSERT ON ty_ix_report_evidence FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_report_evidence_guard();
CREATE TRIGGER ty_ix_report_evidence_frozen BEFORE UPDATE OR DELETE ON ty_ix_report_evidence FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_frozen_guard();
CREATE FUNCTION fn_ty_ix_report_confirm_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE e record;r public.ty_ix_event_root%ROWTYPE;BEGIN
 IF NEW.status='confirmed'AND OLD.status='draft'THEN FOR e IN SELECT*FROM public.ty_ix_report_evidence WHERE report_id=NEW.id ORDER BY root_id,line_id LOOP SELECT*INTO r FROM public.ty_ix_event_root WHERE id=e.root_id FOR SHARE;IF r.head_revision<>e.expected_root_head OR r.latest_inbox_id<>e.inbox_id OR r.approved_punch_id<>e.punch_id OR NOT EXISTS(SELECT 1 FROM public.ty_ix_punch WHERE id=e.punch_id AND status='approved'AND source_hash=e.source_hash)THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='E_TY_CONFLICT: 原卡来源已有新版本，请重新核查后建立核勤草稿';END IF;END LOOP;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_report_confirm BEFORE UPDATE ON ty_time_report_version FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_report_confirm_guard();
CREATE TABLE ty_ix_directory_proposal(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 identity_id bigint NOT NULL REFERENCES ty_ix_identity(id),inbox_id bigint NOT NULL REFERENCES ty_ix_inbox(id),person_id bigint REFERENCES ty_person(id),department_id bigint REFERENCES ty_department(id),
 expected_identity_revision integer NOT NULL,source_hash text NOT NULL,local_hash text NOT NULL,target_name text NOT NULL CHECK(length(btrim(target_name))BETWEEN 1 AND 160),
 reason text NOT NULL CHECK(length(btrim(reason))>=4),evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 status text NOT NULL DEFAULT'proposed'CHECK(status IN('proposed','approved','rejected','disabled')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(connection_id,identity_id,inbox_id,local_hash)
);
CREATE FUNCTION fn_ty_ix_directory_proposal_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE m public.ty_ix_identity%ROWTYPE;i public.ty_ix_inbox%ROWTYPE;r public.ty_ix_event_root%ROWTYPE;n text;BEGIN
 IF TG_OP='UPDATE'AND NEW.status='disabled'AND OLD.status='approved'THEN RETURN NEW;END IF;IF TG_OP='UPDATE'AND OLD.status='approved'AND NEW.status='disabled'THEN RETURN NEW;END IF;SELECT*INTO m FROM public.ty_ix_identity WHERE id=NEW.identity_id;SELECT*INTO i FROM public.ty_ix_inbox WHERE id=NEW.inbox_id;SELECT*INTO r FROM public.ty_ix_event_root WHERE id=i.root_id;
 IF m.external_kind='person'THEN SELECT full_name INTO n FROM public.ty_person WHERE id=m.person_id;ELSE SELECT name INTO n FROM public.ty_department WHERE id=m.department_id;END IF;
 IF m.connection_id IS DISTINCT FROM NEW.connection_id OR m.group_id IS DISTINCT FROM NEW.group_id OR m.company_id IS DISTINCT FROM NEW.company_id OR m.status<>'approved'OR m.revision<>NEW.expected_identity_revision OR i.connection_id IS DISTINCT FROM NEW.connection_id OR r.external_id IS DISTINCT FROM m.external_id OR i.payload_hash IS DISTINCT FROM NEW.source_hash OR r.latest_inbox_id IS DISTINCT FROM i.id OR NEW.target_name IS DISTINCT FROM n OR NEW.person_id IS DISTINCT FROM m.person_id OR NEW.department_id IS DISTINCT FROM m.department_id OR(m.external_kind='person'AND r.event_kind<>'directory_person')OR(m.external_kind='department'AND r.event_kind<>'directory_department')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 目录更新须源于当前映射、快照和本方姓名事实，不改雇佣';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_directory_scope BEFORE INSERT OR UPDATE ON ty_ix_directory_proposal FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_directory_proposal_guard();
CREATE TRIGGER ty_ix_directory_approval BEFORE INSERT OR UPDATE ON ty_ix_directory_proposal FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_approval_guard();
CREATE TRIGGER ty_ix_directory_frozen BEFORE UPDATE OR DELETE ON ty_ix_directory_proposal FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_frozen_guard();
CREATE UNIQUE INDEX ty_ix_one_business_delivery ON ty_ix_job(connection_id,source_key)WHERE kind IN('message.send','task.send');
CREATE FUNCTION fn_ty_ix_lineage_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE j jsonb=to_jsonb(NEW);p public.ty_ix_profile%ROWTYPE;r public.ty_ix_event_root%ROWTYPE;i public.ty_ix_inbox%ROWTYPE;b public.ty_ix_punch%ROWTYPE;BEGIN
 IF TG_TABLE_NAME='ty_ix_job'THEN SELECT*INTO p FROM public.ty_ix_profile WHERE id=NEW.profile_id;IF p.connection_id IS DISTINCT FROM NEW.connection_id OR p.group_id IS DISTINCT FROM NEW.group_id OR p.company_id IS DISTINCT FROM NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 任务与核准运行规则须同连接同范围';END IF;END IF;
 IF TG_TABLE_NAME='ty_ix_inbox'THEN SELECT*INTO r FROM public.ty_ix_event_root WHERE id=NEW.root_id;IF r.connection_id IS DISTINCT FROM NEW.connection_id OR r.group_id IS DISTINCT FROM NEW.group_id OR NEW.job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_ix_job WHERE id=NEW.job_id AND connection_id=NEW.connection_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 收件箱与源事件、采集任务须同连接';END IF;END IF;
 IF TG_TABLE_NAME='ty_ix_event_root'THEN IF NEW.latest_inbox_id IS NOT NULL THEN SELECT*INTO i FROM public.ty_ix_inbox WHERE id=NEW.latest_inbox_id;IF i.root_id IS DISTINCT FROM NEW.id OR i.connection_id IS DISTINCT FROM NEW.connection_id OR i.group_id IS DISTINCT FROM NEW.group_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 来源头不能指向另一事件';END IF;END IF;
 IF TG_OP='UPDATE'AND OLD.latest_inbox_id IS NOT NULL AND NEW.latest_inbox_id IS DISTINCT FROM OLD.latest_inbox_id AND(NEW.latest_inbox_id IS NULL OR NEW.latest_inbox_id<OLD.latest_inbox_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源头不能回退旧载荷';END IF;
 IF NEW.approved_punch_id IS NOT NULL AND(TG_OP='INSERT'OR NEW.approved_punch_id IS DISTINCT FROM OLD.approved_punch_id)THEN SELECT*INTO b FROM public.ty_ix_punch WHERE id=NEW.approved_punch_id;IF b.root_id IS DISTINCT FROM NEW.id OR b.group_id IS DISTINCT FROM NEW.group_id OR b.inbox_id IS DISTINCT FROM NEW.latest_inbox_id OR b.status<>'approved'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 来源采用只能指向本事件当前已核原卡';END IF;END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_job_lineage BEFORE INSERT OR UPDATE ON ty_ix_job FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_lineage_guard();
CREATE TRIGGER ty_ix_inbox_lineage BEFORE INSERT OR UPDATE ON ty_ix_inbox FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_lineage_guard();
CREATE TRIGGER ty_ix_root_lineage BEFORE INSERT OR UPDATE ON ty_ix_event_root FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_lineage_guard();
-- A failed/not-executed logical intent may bind a newly approved transport
-- profile through independent review. Unknown or accepted writes never resume.
ALTER TABLE ty_ix_job ADD COLUMN runtime_profile_id bigint REFERENCES ty_ix_profile(id);
CREATE TABLE ty_ix_job_rebind(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,job_id bigint NOT NULL REFERENCES ty_ix_job(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 from_profile_id bigint NOT NULL REFERENCES ty_ix_profile(id),to_profile_id bigint NOT NULL REFERENCES ty_ix_profile(id),expected_job_revision integer NOT NULL,
 evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),reason text NOT NULL CHECK(length(btrim(reason))>=4),created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,expected_job_revision)
);
CREATE FUNCTION fn_ty_ix_rebind_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE j public.ty_ix_job%ROWTYPE;p public.ty_ix_profile%ROWTYPE;BEGIN
 IF TG_TABLE_NAME='ty_ix_job_rebind'THEN SELECT*INTO j FROM public.ty_ix_job WHERE id=NEW.job_id FOR UPDATE;SELECT*INTO p FROM public.ty_ix_profile WHERE id=NEW.to_profile_id;
 IF j.state NOT IN('blocked','failed')OR j.group_id IS DISTINCT FROM NEW.group_id OR j.revision<>NEW.expected_job_revision OR coalesce(j.runtime_profile_id,j.profile_id)<>NEW.from_profile_id OR p.connection_id<>j.connection_id OR p.group_id<>j.group_id OR p.status<>'approved'OR public.fn_ty_pr_same_actor(NEW.created_by,j.created_by)OR(j.kind NOT LIKE'%.read'AND EXISTS(SELECT 1 FROM public.ty_ix_delivery_receipt WHERE job_id=j.id AND outcome IN('confirmed','unknown','stale_lease')))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 仅确未执行的失败任务可独立重绑，已受理或未知写操作先对账';END IF;
 ELSE IF NEW.runtime_profile_id IS DISTINCT FROM OLD.runtime_profile_id AND NOT EXISTS(SELECT 1 FROM public.ty_ix_job_rebind WHERE job_id=OLD.id AND expected_job_revision=OLD.revision AND from_profile_id=coalesce(OLD.runtime_profile_id,OLD.profile_id)AND to_profile_id=NEW.runtime_profile_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 运行规则重绑须独立核查且沿原任务';END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_job_rebind_guard BEFORE INSERT ON ty_ix_job_rebind FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_rebind_guard();
CREATE TRIGGER ty_ix_job_profile_guard BEFORE UPDATE ON ty_ix_job FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_rebind_guard();
CREATE TRIGGER ty_ix_job_rebind_frozen BEFORE UPDATE OR DELETE ON ty_ix_job_rebind FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_frozen_guard();
CREATE TABLE ty_ix_file_import(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 namespace text NOT NULL,filename text NOT NULL,source_hash text NOT NULL,payload_cipher text NOT NULL,payload_iv text NOT NULL,payload_tag text NOT NULL,
 row_count integer NOT NULL,valid_count integer NOT NULL,issues jsonb NOT NULL,status text NOT NULL CHECK(status IN('invalid','validated','applied')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),committed_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),committed_at timestamptz,
 UNIQUE(connection_id,namespace,source_hash),UNIQUE(id,connection_id,group_id)
);
ALTER TABLE ty_ix_inbox ADD COLUMN file_import_id bigint;
ALTER TABLE ty_ix_inbox ADD CONSTRAINT ty_ix_inbox_file_scope FOREIGN KEY(file_import_id,connection_id,group_id)REFERENCES ty_ix_file_import(id,connection_id,group_id);
CREATE FUNCTION fn_ty_ix_file_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已落来源文件不删除';END IF;
 IF TG_OP='UPDATE'AND OLD.status IS DISTINCT FROM NEW.status AND NOT(OLD.status='validated'AND NEW.status='applied')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源文件状态不回退';END IF;IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['status','revision','committed_by','committed_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','committed_by','committed_at'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 原始证据文件和预检不可覆盖';END IF;
 IF NEW.status='applied'AND(NEW.committed_by IS NULL OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.committed_by)OR NEW.issues<>'[]'::jsonb)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 来源文件须另一有权人独立核定且无错误';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_ix_file_scope BEFORE INSERT OR UPDATE ON ty_ix_file_import FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_scope_guard();
CREATE TRIGGER ty_ix_file_frozen BEFORE INSERT OR UPDATE OR DELETE ON ty_ix_file_import FOR EACH ROW EXECUTE FUNCTION fn_ty_ix_file_guard();
